"""Build the self-contained founder design artifact; no network requests."""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parent
# Comment controller adapted from the existing FLY-2389 Apple-light report.
controller = "(() => {\n  const marker = '【页面意见汇总】FLY-2393';\n  const prefix = 'flywheel-comments:' + location.pathname + ':';\n  const fields = Array.from(document.querySelectorAll('[data-comment]'));\n  const summary = document.getElementById('summary-text');\n  const chunksNode = document.getElementById('chunks');\n  const status = document.getElementById('copy-status');\n  const allButton = document.getElementById('copy-all');\n  let chunks = [];\n  async function copy(text) {\n    try {\n      if (!navigator.clipboard || !navigator.clipboard.writeText) throw new Error('unavailable');\n      await navigator.clipboard.writeText(text);\n    } catch {\n      const field = document.createElement('textarea');\n      field.value = text;\n      field.style.position = 'fixed';\n      field.style.opacity = '0';\n      document.body.appendChild(field);\n      field.select();\n      let ok = false;\n      try { ok = document.execCommand('copy'); } catch { ok = false; }\n      field.remove();\n      if (!ok) { status.textContent = '自动复制失败，请手动选择汇总文字复制。'; return; }\n    }\n    status.textContent = '已复制。粘贴发回即可；本页不会自动发送。';\n  }\n  function render() {\n    chunks = [];\n    let current = marker;\n    for (const field of fields) {\n      const value = field.value.trim();\n      if (!value) continue;\n      const label = '\\n\\n【' + field.dataset.title + '】\\n';\n      let piece = '';\n      const pieces = [];\n      for (const char of value) {\n        if (piece.length + char.length > 1550) { pieces.push(piece); piece = ''; }\n        piece += char;\n      }\n      if (piece) pieces.push(piece);\n      for (const part of pieces) {\n        if ((current + label + part).length > 1800) { chunks.push(current); current = marker; }\n        current += label + part;\n      }\n    }\n    if (current !== marker) chunks.push(current);\n    summary.textContent = chunks.length ? chunks.join('\\n\\n') : '尚无意见。';\n    allButton.disabled = chunks.length === 0;\n    chunksNode.replaceChildren();\n    if (chunks.length > 1) chunks.forEach((part, index) => {\n      const box = document.createElement('div');\n      box.className = 'chunk';\n      const pre = document.createElement('pre');\n      pre.textContent = part;\n      const button = document.createElement('button');\n      button.type = 'button';\n      button.textContent = '复制第 ' + (index + 1) + '/' + chunks.length + ' 段';\n      button.addEventListener('click', () => copy(part));\n      box.append(pre, button);\n      chunksNode.appendChild(box);\n    });\n  }\n  for (const field of fields) {\n    try { field.value = localStorage.getItem(prefix + field.dataset.comment) || ''; }\n    catch { status.textContent = '浏览器未允许本地保存，仍可填写并复制。'; }\n    field.addEventListener('input', () => {\n      try { localStorage.setItem(prefix + field.dataset.comment, field.value); }\n      catch { status.textContent = '本地保存不可用，请及时复制意见。'; }\n      render();\n    });\n  }\n  allButton.addEventListener('click', () => copy(chunks.join('\\n\\n')));\n  render();\n})();"
css = '''*{box-sizing:border-box}body{margin:0;background:#f5f5f7;color:#1d1d1f;font:16px/1.75 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1000px;margin:auto;padding:44px 20px 72px}h1{font-size:clamp(29px,5vw,46px);line-height:1.3;letter-spacing:-.8px;margin:14px 0 30px}h2{font-size:24px;line-height:1.4;margin:0 0 16px}p{margin:12px 0}.eyebrow{font-size:13px;color:#65656d;letter-spacing:.7px}.card{background:#fff;border:1px solid #e3e3e8;border-radius:16px;padding:28px;margin:22px 0}.lead{font-size:23px;line-height:1.6}.note{font-size:14px;color:#62626a}.pending{border:1px dashed #bd8a36;background:#fff9ee;padding:20px;border-radius:8px;margin:20px 0;color:#795218}.pending strong{display:block;font-size:15px}.status{display:inline-block;font-size:13px;color:#175899;background:#edf5ff;border:1px solid #d4e6fa;padding:4px 12px;border-radius:20px}details{margin:12px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace}table{border-collapse:collapse;width:100%;font-size:15px}th,td{padding:12px 10px;border-bottom:1px solid #e9e9ee;text-align:left;vertical-align:top}th{background:#fafafa}.comment{border-top:1px solid #eee;margin-top:24px;padding-top:16px}label{display:block;font-size:13px;color:#65656d;margin-bottom:6px}textarea{width:100%;min-height:80px;padding:12px;font:inherit;font-size:15px;border:1px solid #c9c9d0;border-radius:8px;background:#fdfdff;resize:vertical}textarea:focus{outline:2px solid #0071e366;border-color:#0071e3}button{font:inherit;font-size:14px;padding:10px 16px;border:0;border-radius:8px;background:#0071e3;color:white;cursor:pointer;margin:10px 8px 0 0}button:disabled{opacity:.4;cursor:default}#summary-text{background:#f5f5f7;padding:16px;border-radius:8px;min-height:64px;font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere}#copy-status{min-height:1.5em;color:#62626a;font-size:14px}.chunk{background:#fafafa;border-radius:8px;padding:14px;margin-top:12px}.chunk pre{font:14px/1.7 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;margin:0}a{color:#0071e3}svg{max-width:100%;height:auto}@media(max-width:600px){main{padding:22px 12px 44px}.card{padding:20px 16px;border-radius:12px}h2{font-size:21px}td,th{padding:9px 5px;font-size:12px}.lead{font-size:20px}}'''

def diagram(name, label):
    svg = ROOT / (name + '.svg')
    if svg.exists():
        return svg.read_text()
    source = escape((ROOT / (name + '.mmd')).read_text())
    return '<div class="pending" role="note"><strong>DIAGRAM PENDING LOCAL RENDER</strong>本机图形渲染程序启动权限被拒，两次本地尝试均失败。图源已保留；本页暂不能展示渲染图。</div><details><summary>'+escape(label)+'原文（Mermaid 图源）</summary><pre>'+source+'</pre></details>'

def comment(key, title):
    return '<div class="comment"><label for="comment-'+escape(key)+'">对「'+escape(title)+'」的意见</label><textarea id="comment-'+escape(key)+'" data-comment="'+escape(key)+'" data-title="'+escape(title)+'" placeholder="写在这里，自动保存在本页的浏览器中"></textarea></div>'

def section(key, title, body):
    return '<section class="card" data-section="'+escape(key)+'"><h2>'+escape(title)+'</h2>'+body+comment(key,title)+'</section>'

cards=[]
cards.append(section('flow','各项目按自己的时间发内部测试版', '''<p class="lead">由 Bridge 逐项目判断何时到期，再交给对应仓库发布；客户每周发布继续沿用现有流程。</p><p><b>Bridge</b> 是协调自动任务的服务。<b>beta</b> 是先给内部使用的测试版。<b>工作流</b> 是一组预先写好的构建和发布步骤。</p>'''+diagram('d1-flow','核心流程图')+'''<p class="note">每分钟检查一次是否到期。外部执行平台排队可能延迟真正发布，页面会分别记录到期、受理、开始和发布时间。</p>'''))
cards.append(section('cadence','接管前后，节奏清楚可见', '''<table><thead><tr><th>项目 / 状态</th><th>接管前基线</th><th>接管后目标</th></tr></thead><tbody><tr><td>flywheel（PRD 中称 Flavio）</td><td>每 6 小时</td><td>明确配置每 6 小时</td></tr><tr><td>GeoForge3D</td><td>产品基线为 6 小时；未找到实际 beta 入口</td><td>每 24 小时；入口未接入时保持未激活</td></tr><tr><td>其他已接入项目</td><td>原有入口继续运行</td><td>不填频率时默认 24 小时</td></tr></tbody></table><p>默认 24 小时只在该项目真正接管后生效。<b>GeoForge3D 目前缺少明确的内部测试版发布工作流</b>，状态页必须直说“尚未激活”，并保留目标频率。</p><p class="note">Lead 已确认：不拿 Geo 的生产部署工作流顶替 beta，不把对外客户发布扩展到其他项目。</p>'''))
cards.append(section('model','项目身份、频率、进度各有唯一来源', diagram('d2-model','数据关系图')+'''<table><thead><tr><th>保存什么</th><th>在哪里决定</th><th>为什么</th></tr></thead><tbody><tr><td>稳定项目标识与对应仓库</td><td>现有项目名册</td><td>改展示名不会串项目</td></tr><tr><td>每隔几小时、使用哪个工作流</td><td>该项目自己的配置文件</td><td>改 A 的频率不会改变 B</td></tr><tr><td>旧定时器 / 暂停 / Bridge 接管</td><td>目标仓库的一个控制值</td><td>避免两个入口同时发版</td></tr><tr><td>下次时间、本次任务与发布结果</td><td>可恢复的进度账本</td><td>重启后继续核对，不从零重发</td></tr></tbody></table><p>调度任务标识只负责找到这一轮结果，不会被当作“强制生成一个新版本”的指令。同一份代码已发布时，记为“无新代码”，不会凑数再发。</p>'''))
cards.append(section('recovery','失败只留在自己的项目里', '''<ul><li>一个项目配置错误、凭据失效或发布卡住，另一项目仍可按自己的周期推进。</li><li>平台收到请求不代表已经发布；系统还要核对运行记录和发布回执。</li><li>重启、网络丢响应时，先继续查询同一任务。无法确认就显示“需要处理”，不假装完成。</li><li>停机错过多个周期，只合并补一轮，避免恢复后连续发一串旧版本。</li></ul><p>暂停先阻止新任务，已经受理的任务可能仍会完成。切回旧 6 小时入口之前，必须把所有在途任务核对并排空。</p>'''))
cards.append(section('tradeoffs','为什么采用这个方案', '''<table><thead><tr><th>方案</th><th>取舍</th></tr></thead><tbody><tr><td>采用：Bridge 管到期，各仓工作流管发布</td><td>项目节奏集中可查；保留现有构建和发布权限。需要账本、回执和明确交接。</td></tr><tr><td>不采用：每个仓各写定时规则</td><td>改动少，但频率散落，Bridge 无法统一知道接管与运行结果。</td></tr><tr><td>不采用：Bridge 本机直接打包发布</td><td>会让协调服务承担长时间构建和更多发布凭据，扩大故障影响。</td></tr></tbody></table><p>本次只支持按整小时设置间隔，不增加复杂日历规则。项目仍共享宿主与执行平台配额，因此这是调度逻辑隔离，不承诺物理故障完全隔离。</p>'''))
cards.append(section('evidence','怎样验收，以及这份设计的边界', '''<p><b>调度验收：</b>两个已绑定的测试项目设置 6 小时与 24 小时，推进 48 小时，分别观察 8 次和 2 次到期任务；加入重启、卡住、频率变化和重复请求反例。</p><p><b>真实发布验收：</b>要有两个项目各自的真实内部版本、运行链接和时间回执。模拟发布器通过只证明调度隔离，不能写成“两项目 beta 已上线”。Geo 入口未补齐时，这项证据仍未完成。</p><p><b>客户流程回归：</b>现有每周发布、健康判据聚合、自动发布决策不新增对此功能的依赖，发布权限与共同串行保护保持原合同。</p><p>当前交付是工程设计与实施计划；没有编写调度实现、修改生产配置或发布任何版本。后续实现和独立验证由既有工作流推进。</p><p class="note">B6 只影响“每项目 beta 分频”的目标何时成立，不阻塞 flywheel-only 每周对外发布。</p>'''))
summary = '''<section class="card" data-section="summary"><h2>页面意见汇总</h2><p class="note">意见只保存在当前浏览器，不会自动发送。复制后发回即可；这是修改反馈，不代表批准。</p>'''+comment('summary','整体意见')+'''<div id="summary-text" aria-live="polite"></div><button id="copy-all" type="button" disabled>复制全部意见</button><div id="chunks"></div><p id="copy-status" role="status"></p></section>'''
status='工程设计 · 待有效评审'
review=ROOT/'review-result.json'
if review.exists() and json.loads(review.read_text()).get('effectiveVerdict') == 'APPROVED':
    status='工程设计已通过评审 · 尚未实施'
html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FLY-2393 · 每项目 beta 分频</title><style>'+css+'</style></head><body><main><div class="eyebrow">FLY-2393 · B6 独立设计 · 2026-09-10</div><h1>快项目快一点，<br>稳项目少打扰。</h1><span class="status">'+escape(status)+'</span>'+''.join(cards)+summary+'</main><script nonce="__CSP_NONCE__">'+controller+'</script></body></html>'
(ROOT/'founder-design.html').write_text(html)
print('generated founder-design.html', len(html.encode()), 'bytes')
